-- MP-0014: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0014: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='wawasan' and type='party') then raise exception 'MP-0014: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('ahmad-samsuri-mokhtar','siti-mastura-muhammad','wan-saiful-wan-jan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0014: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kemaman','kepala batas','tasek gelugor') and slug not in ('ahmad-samsuri-mokhtar','siti-mastura-muhammad','wan-saiful-wan-jan')) then raise exception 'MP-0014: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0014:%' and (m.source_type <> 'editorial' or e.slug not in ('ahmad-samsuri-mokhtar','siti-mastura-muhammad','wan-saiful-wan-jan') or m.import_key not like 'MP-0014:' || e.slug || ':%')) then raise exception 'MP-0014: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ahmad-samsuri-mokhtar','Ahmad Samsuri Mokhtar','opposition','Menteri Besar of Terengganu; Chairman of Perikatan Nasional; Member of the Dewan Rakyat','Kemaman','Terengganu','Ahmad Samsuri Mokhtar represents Kemaman, Terengganu, in the Dewan Rakyat. Current role: Menteri Besar of Terengganu; Chairman of Perikatan Nasional; Member of the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4286','/portraits/ahmad-samsuri-mokhtar.webp','https://www.parlimen.gov.my/images/webuser/ahli/2023/YB%20Samsuri.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4286"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}, {"label": "Terengganu · Menteri Besar", "url": "https://www.trdi.my/ecrl-mampu-jadi-pemangkin-industri-perlu-dimanfaatkan-pks-ahmad-samsuri"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'siti-mastura-muhammad','Siti Mastura Muhammad','opposition','Member of the Dewan Rakyat','Kepala Batas','Pulau Pinang','Siti Mastura Muhammad represents Kepala Batas, Pulau Pinang, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4080','/portraits/siti-mastura-muhammad.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P041.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4080"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wan-saiful-wan-jan','Wan Saiful Wan Jan','opposition','Member of the Dewan Rakyat','Tasek Gelugor','Pulau Pinang','Wan Saiful Wan Jan represents Tasek Gelugor, Pulau Pinang, in the Dewan Rakyat. A Parti Wawasan Negara member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4081','/portraits/wan-saiful-wan-jan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P042.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4081"}, {"label": "Wawasan · announced leadership, 21 Jun 2026", "url": "https://www.thestar.com.my/news/nation/2026/06/21/parti-wawasan-negara-unveils-central-leadership-line-up"}]'::jsonb from public.entities parent where parent.slug='wawasan' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('ahmad-samsuri-mokhtar','siti-mastura-muhammad','wan-saiful-wan-jan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0014: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0014:ahmad-samsuri-mokhtar:nine-million-visitors','Target nine million visitor arrivals in Terengganu during 2026','Economy',null,null,'2026-12-31','2025-12-17','https://www.trdi.my/negeri-bahagia-sasar-9-juta-pelawat-pada-2026',null,null,'The target was announced by Razali Idris while representing Menteri Besar Ahmad Samsuri at the state tourism awards.','This is a shared state-government target, not solely the MP’s achievement. The cited 8.512 million arrivals concern 2025 and cannot measure the 2026 target. A full-year 2026 result was not verified.','2026-11-09','editorial',false from public.entities e where e.slug='ahmad-samsuri-mokhtar' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

